  const actionsList: ActionEntry[] = [];

  await forEachSequential(deps.toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, deps.allowedTools)) {
      deps.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${deps.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await deps.logAutopilotEvent(deps.workspaceId, deps.contactId, toolName, {}, blockedResult);
      return;
    }
    const toolArgs = parseToolArgs(toolCall.function.arguments);
    if (toolCall.function.arguments && Object.keys(toolArgs).length === 0 && toolCall.function.arguments.trim() !== '{}') {
      deps.logger.warn(`Failed to parse tool args for ${toolName}`);
    }
    const result = await deps.executeToolAction(
      deps.workspaceId,
      deps.contactId,
      deps.phone,
      toolName,
      toolArgs,
      deps.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await deps.logAutopilotEvent(deps.workspaceId, deps.contactId, toolName, toolArgs, result);
  });

  return actionsList;
}

import {
  executePredecidedAgentActions,
  buildPredecidedActionDraft,
} from './unified-agent-predecided-actions.part';
import { actionSucceeded } from './unified-agent-tool-router.helpers';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import type { ActionEntry, PredecidedAction } from './unified-agent.types';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import type OpenAI from 'openai';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentPredecidedActions(deps: {
  predecidedActions: PredecidedAction[];
  allowedTools?: string[];
  workspaceId: string;
  contactId: string;
  phone: string;
  message: string;
  context?: UnknownRecord;
  channel: string;
  openai: OpenAI | null;
  writerModel: string;
  fallbackWriterModel: string;
  response: UnifiedAgentResponseService;
  agentRuntime?: AgentRuntimeContextService;
  conversationHistoryLength: number;
  executeToolAction: (
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: Record<string, unknown>,
    context?: UnknownRecord,
  ) => Promise<unknown>;
  logAutopilotEvent: (
    workspaceId: string,
    contactId: string,
    tool: string,
    args: Record<string, unknown>,
    result: unknown,
  ) => Promise<unknown>;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const actionsList = await executePredecidedAgentActions({
    ...(deps.allowedTools !== undefined ? { allowedTools: deps.allowedTools } : {}),
    contactId: deps.contactId,
    ...(deps.context !== undefined ? { context: deps.context } : {}),
    executeTool: deps.executeToolAction,
    logAutopilotEvent: deps.logAutopilotEvent,
    phone: deps.phone,
    predecidedActions: deps.predecidedActions,
    workspaceId: deps.workspaceId,
  });
  const intent = deps.response.extractIntent(actionsList, deps.message);
  const draftedReply = await deps.response.composeWriterReply(
    deps.openai,
    deps.writerModel,
    deps.fallbackWriterModel,
    {
      workspaceId: deps.workspaceId,
      customerMessage: deps.message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: deps.conversationHistoryLength,
    },
  );

  await recordAgentRuntimeTurn(
    {
      workspaceId: deps.workspaceId,
      channel: deps.channel,
      userMessage: deps.message,
      ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
      contactId: deps.contactId,
      intent,
      confidence: actionsList.length > 0 ? 0.85 : 0.55,
      actions: actionsList.map((action) => ({
        toolName: action.tool,
        success: actionSucceeded(action.result),
        result: action.result,
      })),
    },
    deps.agentRuntime,
  );

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

import OpenAI from 'openai';
import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import { chatCompletionWithFallback } from './openai-wrapper';
import { processUnifiedAgentToolCalls } from './unified-agent-tool-call-processing.helpers';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import { actionSucceeded } from './unified-agent-tool-router.helpers';
import type { ActionEntry } from './unified-agent.types';
import type { PlanLimitsService } from '../billing/plan-limits.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { AgentRuntimeContextService } from './agent-runtime';

type UnknownRecord = Record<string, unknown>;

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

interface IncomingMessageLogger {
  error: (msg: string) => void;
}

export async function processIncomingUnifiedAgentMessage(
  messages: ChatCompletionMessageParam[],
  deps: {
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    channel: string;
    allowedTools?: string[];
    context?: UnknownRecord;
    openai: OpenAI | null;
    primaryBrainModel: string;
    fallbackBrainModel: string;
    writerModel: string;
    fallbackWriterModel: string;
    planLimits: PlanLimitsService;
    response: UnifiedAgentResponseService;
    agentRuntime?: AgentRuntimeContextService;
    logger: IncomingMessageLogger;
    conversationHistoryLength: number;
    executeToolAction: (
      workspaceId: string,
      contactId: string,
      phone: string,
      tool: string,
      args: Record<string, unknown>,
      context?: UnknownRecord,
    ) => Promise<unknown>;
    logAutopilotEvent: (
      workspaceId: string,
      contactId: string,
      tool: string,
      args: Record<string, unknown>,
      result: unknown,
    ) => Promise<unknown>;
  },
): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  let llmResponse: OpenAI.Chat.ChatCompletion;
  try {
    await deps.planLimits.ensureTokenBudget(deps.workspaceId);
    const openaiInstance = deps.openai;
    if (!openaiInstance) {
      const error = new Error();
      error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
      throw error;
    }
    llmResponse = await chatCompletionWithFallback(
      openaiInstance,
      {
        model: deps.primaryBrainModel,
        messages,
        temperature: 0.82,
        top_p: 0.9,
      },
      deps.fallbackBrainModel,
    );
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
    deps.logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
    return deps.response.buildFallbackResult(deps.message);
  }
  if (!llmResponse) {
    return deps.response.buildFallbackResult(deps.message);
  }
  const firstChoice = llmResponse.choices[0];
  if (!firstChoice) {
    return deps.response.buildFallbackResult(deps.message);
  }
  await deps.planLimits
    .trackAiUsage(deps.workspaceId, llmResponse.usage?.total_tokens ?? 500)
    .catch(() => {});

  const assistantMessage = firstChoice.message;
  let actionsList: ActionEntry[] = [];

  const executeTools = deps.context?.executeTools !== false;
  if (executeTools && assistantMessage.tool_calls && assistantMessage.tool_calls.length > 0) {
    actionsList = await processUnifiedAgentToolCalls({
      toolCalls: assistantMessage.tool_calls,
      allowedTools: deps.allowedTools,
      workspaceId: deps.workspaceId,
      contactId: deps.contactId,
      phone: deps.phone,
      context: deps.context,
      logger: deps.logger as { warn: (msg: string) => void },
      executeToolAction: deps.executeToolAction,
      logAutopilotEvent: deps.logAutopilotEvent,
    });
  }

  const intent = deps.response.extractIntent(actionsList, deps.message);
  const confidence = deps.response.calculateConfidence(actionsList, llmResponse);
  const draftedReply = await deps.response.composeWriterReply(
    deps.openai,
    deps.writerModel,
    deps.fallbackWriterModel,
    {
      workspaceId: deps.workspaceId,
      customerMessage: deps.message,
      assistantDraft: assistantMessage.content,
      actions: actionsList,
      historyTurns: deps.conversationHistoryLength,
    },
  );

  await recordAgentRuntimeTurn(
    {
      workspaceId: deps.workspaceId,
      channel: deps.channel,
      userMessage: deps.message,
      ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
      contactId: deps.contactId,
      intent,
      confidence,
      actions: actionsList.map((action) => ({
        toolName: action.tool,
        success: actionSucceeded(action.result),
        result: action.result,
      })),
    },
    deps.agentRuntime,
  );

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence,
  };
}

